def transform(grid):
    rows = len(grid)
    width = len(grid[0])
    # The separator color appears only in its solid divider column.
    divider = next(c for c in range(width)
                   if all(grid[r][c] == grid[0][c] for r in range(rows))
                   and all(grid[r][j] != grid[0][c]
                           for r in range(rows) for j in range(width) if j != c))
    panel_width = min(divider, width - divider - 1)
    left_start = divider - panel_width
    right_start = divider + 1
    left_colors = {grid[r][c] for r in range(rows) for c in range(left_start, divider)}
    right_colors = {grid[r][c] for r in range(rows) for c in range(right_start, right_start + panel_width)}
    common_color = next(iter(left_colors & right_colors))
    return [[3 if grid[r][left_start + c] == grid[r][right_start + c] else common_color
             for c in range(panel_width)] for r in range(rows)]
